+}
+
+func TestInstallHooks_AlsoInstallsVSCodeFile(t *testing.T) {
+	// No t.Parallel(): t.Chdir mutates process-global cwd.
+	tempDir := t.TempDir()
+	t.Chdir(tempDir)
+
+	ag := &CopilotCLIAgent{}
+	_, err := ag.InstallHooks(context.Background(), false, false)
